ee:message.ee:set-payload:
%dw 2.0
output application/json
var cuerpoVariable = payload.MensajeABD.CuerpoMensaje  match {
    case obj if obj.SolicitudNIP is Object -> obj.SolicitudNIP
    case obj if obj.RespuestaSolicitudNIP is Object -> obj.RespuestaSolicitudNIP
    case obj if obj.SolicitudReenvioNIP is Object -> obj.SolicitudReenvioNIP
    case obj if obj.RespuestaSolicitudReenvioNIP is Object -> obj.RespuestaSolicitudReenvioNIP
    case obj if obj.SolicitudPortacion is Object -> obj.SolicitudPortacion
    case obj if obj.ReplicaSolicitudPortacion is Object -> obj.ReplicaSolicitudPortacion
    case obj if obj.RespuestaSolicitudPortacionDonante is Object -> obj.RespuestaSolicitudPortacionDonante
    case obj if obj.ReplicaRespuestaSolicitudPortacionDonante is Object -> obj.ReplicaRespuestaSolicitudPortacionDonante
    case obj if obj.SolicitudDeProgramacionPortacion is Object -> obj.SolicitudDeProgramacionPortacion
    case obj if obj.ProgramacionPortacion is Object -> obj.ProgramacionPortacion
    case obj if obj.ConfirmacionProgramacionPortacion is Object -> obj.ConfirmacionProgramacionPortacion
    case obj if obj.RespuestaSolicitudCancelacion is Object -> obj.RespuestaSolicitudCancelacion
    case obj if obj.RechazoPortacion is Object -> obj.RechazoPortacion
    case obj if obj.ErrorDetectadoABD is Object -> obj.ErrorDetectadoABD
    else -> {}
}
---
{
    "DireccionAbonado": cuerpoVariable.DireccionAbonado,
    "IdProceso": payload.MensajeABD.CabeceraMensaje.IdentificadorProceso,
    "IdMensaje": payload.MensajeABD.CabeceraMensaje.IdentificadorMensaje,
    "IdIntegracion": vars.portabilityResponse[0].IdIntegracion default "",
    "NumeroRepresentante": cuerpoVariable.NumeroRepresentante,
    "Numeracion": vars.portabilityResponse[0].Numeracion default cuerpoVariable.ListaNumeracionNip.*NumeracionNip map Numero: $.Numero,
    "TipoMensaje": payload.MensajeABD.CabeceraMensaje.TipoMsg,
    "FechaCreacionMsg": payload.MensajeABD.CabeceraMensaje.FechaCreacionMsg as LocalDateTime {format: "yyyyMMddHHmmss"} as DateTime >> "America/Bogota",
    "Emisor": payload.MensajeABD.CabeceraMensaje.Emisor,
    "Donante": cuerpoVariable.Donante default "",
    "Sistema_Origen": vars.headers.system,
    "RespuestaSolicitud": {
        "RespuestaABD": if (payload.MensajeABD.CabeceraMensaje.TipoMsg == "1002") null 
        			else if(["9999", "9998"] contains payload.MensajeABD.CabeceraMensaje.TipoMsg) "ERROR" 
        			else cuerpoVariable.RespuestaABD default "1",
        "NumeracionRechazada": 
//casos especiales: 0004 y 9998
        if (["0004", "9998"] contains payload.MensajeABD.CabeceraMensaje.TipoMsg)
        		 cuerpoVariable.CodigosRechazo.*CodigoRechazo default [] map ((item, index) -> {
        		 	"Numero" : vars.portabilityResponse[0].Numeracion[0].Numero,
                	"CodigoRechazo" : item,
                	"DescripcionCodigo" : (vars.codigos_rechazo.valor filter ($.codigo == item)).nombre_valor //buscar el nombre_valor del codigo rechazo
        		 })
//casos sin rechazos
        	else if(["1002", "1005", "1007"] contains payload.MensajeABD.CabeceraMensaje.TipoMsg) []
//casos con numeros rechazados
        	else flatten((if (!isEmpty(cuerpoVariable.ListaNumeracionRechazada)) 
        			cuerpoVariable.ListaNumeracionRechazada.NumeracionRechazada //1004
        			else if (!isEmpty(cuerpoVariable.NumeracionRechazada))
                        cuerpoVariable.NumeracionRechazada //0002
        			else cuerpoVariable.NumeracionesRechazadas.*NumeracionRechazada //9999 y 2002
                    default [] 
        	) map ((item, index) -> item.CodigosRechazo.CodigoRechazo map ((it, in) -> {
                "Numero" : item.Numero,
                "CodigoRechazo" : it,
                "DescripcionCodigo" : (vars.codigos_rechazo.resultados[0].valor filter ($.codigo == it))[0].nombre_valor //buscar el nombre_valor del codigo rechazo
            	})))

    }
//    "ActualizacionExtractor": "1"
  }
